---@class CollectData
CollectData = class("CollectData")
function CollectData:initialize()
    self.configIndex = 0
    self.exchangePropId = 0
    ---獎品數量
    self.exchangePropNum = 0
    self.needPropTable ={}
    ---兌換次數
    self.exchangeSum =0
    self.exchangeLimit =0
end

---@param config dictwordexch_config_cell
function CollectData:SetDataByWordConfig(config)
    self.configIndex = config.C_ID
    self.exchangePropId = config.exchpropid
    local exchangeProp = stringSplit(config.exchpropid,":")
    self.exchangePropId = tonumber(exchangeProp[1])
    self.exchangePropNum = tonumber(exchangeProp[2])
    self.exchangeLimit = config.exchlimit
    local needProps = stringSplit(config.needprops,":")
    for i = 1, #needProps do
        table.insert(self.needPropTable,tonumber(needProps[i]))
    end
end
---@param msg SC_ActWordExch
function CollectData:SetDataByMsg(msg)
   self.exchangeSum = msg.exchsum
end

function CollectData:GetExchangePropsId()
    return self.exchangePropId
end

function CollectData:GetExchangePropsNum()
    return self.exchangePropNum
end

function CollectData:GetNeedPropTable()
    return self.needPropTable
end

function CollectData:IsCanExchange()
    for i = 1,#self.needPropTable do
        local num =  KnapsackDataManager:Get():GetArticleCountByCfgid(self.needPropTable[i])
        if num<=0 then
            return false
        end
    end
    return true
end


