---@return CollectData
function CollectDataManager:GetCollectDataByIndex(index,actId)
    actId=actId==nil and self.curConfig.actId or actId
    if self.CollectDataTab[actId] and self.CollectDataTab[actId][index] then
        return self.CollectDataTab[actId][index]
    end
end

---@return CollectData
function CollectDataManager:GetCollectDataByConfigIndex(configIndex,actId)
    actId=actId==nil and self.curConfig.actId or actId
    for i = 1, #self.CollectDataTab[actId] do
        if self.CollectDataTab[actId][i].configIndex == configIndex then
            return self.CollectDataTab[actId][i]
        end
    end
    return nil
end

function CollectDataManager:InitActCollectTable(collectTable)
   if  self.curConfig == CollectConfigDefault.CollectWords then
       ---@type dictwordexch_config
       local tab = ClientDataManager:Get():GetDataTable(ConfigNames.dictwordexch_config)
       local configTab = tab.GetConfigData()
       for i = 1, #configTab  do --#configTab
           local data = CollectData()
           data:SetDataByWordConfig(configTab[i])
           table.insert(collectTable,data)
       end
   end
end

